	t.Fatal("the stream does not carry the page state")
}
for _, key := range []string{"7d", "14d"} {
	if !strings.Contains(body, `href="/region?r=fra&amp;range=`+key+`"`) {
		t.Errorf("the global picker lacks %s", key)
	}
}

