func overviewRollup(cell string, observed time.Time, peers []string) globalview.Rollup {
	rollup := globalview.Rollup{Version: globalview.Version, Cell: cell, ObservedAt: observed,
		Health:      globalview.Health{Status: globalview.Healthy},
		Controllers: globalview.Controllers{Expected: 3, Ready: 3, Leader: cell + "-ctl-1"},
		Totals: globalview.Totals{Nodes: 12, Ready: 12, CPUCores: 96, CPUUsedCores: 24,
			MemoryBytes: 384 << 30, MemoryUsedBytes: 192 << 30, DiskBytes: 6000 << 30, DiskUsedBytes: 1200 << 30,
			NetworkRxBps: 12000, NetworkTxBps: 6000, Load1: 6},
		Replication: globalview.Replication{LagSeconds: floatPtr(1.5)},
		Cost:        &globalview.Cost{Currency: "USD", PerHour: 12.5, MonthForecast: 9000, ObservedAt: observed},
		Autoscale: globalview.Autoscale{Services: []globalview.Scaling{
			{Service: "api", Replicas: 3, Goal: 3}, {Service: "worker", Replicas: 2, Goal: 4},
			{Service: "db", Replicas: 1, Goal: 1}, {Service: "cache", Replicas: 2, Goal: 2}}},
	}
	for index := range 12 {
		rollup.Nodes = append(rollup.Nodes, globalview.Node{Name: fmt.Sprintf("%s-n%02d", cell, index),
			Health: globalview.NodeOK, ReportedAt: observed, CPU: floatPtr(0.25), CPUCores: 8,
			MemoryBytes: 32 << 30, MemoryUsedBytes: 16 << 30, DiskBytes: 500 << 30, DiskUsedBytes: 100 << 30,
			NetworkRxBps: floatPtr(1000), NetworkTxBps: floatPtr(500), Load1: floatPtr(0.5),
			Services: []globalview.Service{{Role: "controller", State: "ready", Digest: "sha256:abc"},
				{Role: "terrabase", State: "serving"}, {Role: "nats", State: "ready"}},
			Filesystems: []globalview.Filesystem{{Role: "root", SizeBytes: 100 << 30, UsedBytes: 40 << 30},
				{Role: "state", SizeBytes: 400 << 30, UsedBytes: 60 << 30}}})
	}
	for index := range 4 {
		rollup.Volumes = append(rollup.Volumes, globalview.Volume{ID: fmt.Sprintf("%s-vol-%d", cell, index),
			Node: fmt.Sprintf("%s-n%02d", cell, index), State: "attached"})
	}
	for _, peer := range peers {
		rollup.Links = append(rollup.Links, globalview.Link{Region: peer, Reach: decisionlog.RegionOK,
			RTTMillis: floatPtr(40), LagSeconds: floatPtr(2), ObservedAt: observed})
	}
	for index := range 6 {
		rollup.Routes = append(rollup.Routes, globalview.Route{From: fmt.Sprintf("%s-ctl-%d", cell, index),
			To: cell + "-ctl-1", RTTMillis: floatPtr(0.4)})
	}
	for index := range 10 {
		rollup.Errors = append(rollup.Errors, globalview.Error{At: observed.Add(-time.Duration(index) * time.Minute),
			Level: "ERROR", Component: "orchestrator", Message: "lease renewal slow", Count: index + 1,
			Nodes: []string{cell + "-n01", cell + "-n02", cell + "-n03"}})
	}
	for index := range 10 {
		rollup.Databases = append(rollup.Databases, globalview.Database{ID: fmt.Sprintf("%s-db-%d", cell, index),
			Project: cell + "-project", ReplicationBytesPerSecond: float64(1000 * (index + 1)), LagSeconds: 1})
	}
	return rollup
}

func neverLocal(t *testing.T) func(context.Context) regionview.Summary {
	return func(context.Context) regionview.Summary {
		t.Error("the page loaded this region's summary")
		return regionview.Summary{}
	}
}

func NewView(local string, regions func() []string, now func() time.Time) *View {
	if now == nil {
		now = time.Now
	}
	return &View{
		local:       normalize(local),
		regions:     regions,
		now:         now,
		rollups:     map[string]*Rollup{},
		persisted:   map[string]time.Time{},
		persistedAt: map[string]time.Time{},
		changed:     make(chan struct{}),
	}
}

// Regions lists local first, then every other listed region by cell.
func (v *View) Regions() []Region {
	v.mu.Lock()
	defer v.mu.Unlock()
	cells := v.listed()
	out := make([]Region, 0, len(cells))
	for _, cell := range cells {
		out = append(out, v.region(cell))
	}
	return out
}

// Region returns one listed region; false when cell is not listed.
func (v *View) Region(cell string) (Region, bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	cell = normalize(cell)
	if !slices.Contains(v.listed(), cell) {
		return Region{}, false
	}
	return v.region(cell), true
}

// Changed returns a channel closed on the next accepted rollup.
func (v *View) Changed() <-chan struct{} {
	v.mu.Lock()
	defer v.mu.Unlock()
	return v.changed
}

// Accept keeps r when it is newer than the held rollup of its cell.
func (v *View) Accept(r Rollup) bool {
	v.mu.Lock()
	defer v.mu.Unlock()
	if validate(r, v.now()) != nil {
		return false
	}
	held := v.rollups[r.Cell]
	if held != nil && !r.ObservedAt.After(held.ObservedAt) {
		return false
	}
	if held == nil && len(v.rollups) >= maxRegions {
		v.prune()
		if len(v.rollups) >= maxRegions {
			return false
		}
	}
	v.rollups[r.Cell] = &r
	close(v.changed)
	v.changed = make(chan struct{})
	return true
}

}

// listed is local first, then every other listed region sorted. Callers hold mu.
func (v *View) listed() []string {
	var others []string
	if v.regions != nil {
		for _, raw := range v.regions() {
			cell := normalize(raw)
			if cell == "" || cell == v.local || slices.Contains(others, cell) {
				continue
			}
			others = append(others, cell)
		}
	}
	slices.Sort(others)
	if v.local == "" {
		return others
	}
	return append([]string{v.local}, others...)
}

// region reads one listed cell. Callers hold mu.
func (v *View) region(cell string) Region {
	r := v.rollups[cell]
	return Region{
		Cell:   cell,
		Rollup: r,
		Stale:  r != nil && v.now().Sub(r.ObservedAt) > StaleAfter,
	}
}

func (page page) pathValues(request *http.Request) (map[string]string, bool) {
	names := page.pathNames()
	if len(names) == 0 {
		return nil, true
	}
	values := make(map[string]string, len(names))
	for _, name := range names {
		value := request.PathValue(name)
		if name == "r" {
			value = strings.ToLower(value)
			if !validRegion(value) {
				return nil, false
			}
		} else if value == "" || !validToken(value) {
			return nil, false
		}
		values[name] = value
	}
	return values, true
}

func find[T any](items []T, match func(T) bool) (T, bool) {
	if index := slices.IndexFunc(items, match); index >= 0 {
		return items[index], true
	}
	var zero T
	return zero, false
}

func regionNamed(regions []globalview.Region, cell string) (globalview.Region, bool) {
	return find(regions, func(region globalview.Region) bool { return region.Cell == cell })
}

// A region without a rollup has no nodes, volumes or autoscale state.

func nodeNamed(region globalview.Region, name string) (globalview.Node, bool) {
	if region.Rollup == nil {
		return globalview.Node{}, false
	}
	return find(region.Rollup.Nodes, func(node globalview.Node) bool { return node.Name == name })
}

func volumeNamed(region globalview.Region, id string) (globalview.Volume, bool) {
	if region.Rollup == nil || region.Rollup.VolumesUnavailable {
		return globalview.Volume{}, false
	}
	return find(region.Rollup.Volumes, func(volume globalview.Volume) bool { return volume.ID == id })
}

func scalingNamed(region globalview.Region, role string) (globalview.Scaling, bool) {
	if region.Rollup == nil {
		return globalview.Scaling{}, false
	}
	return find(region.Rollup.Autoscale.Services, func(scaling globalview.Scaling) bool { return scaling.Service == role })
}

func serviceNamed(node globalview.Node, role string) (globalview.Service, bool) {
	return find(node.Services, func(service globalview.Service) bool { return service.Role == role })
}

// Missing observations cannot establish that a resource is absent.
func resourceMissing(region globalview.Region, kind, name string) string {
	subject := kind + " " + name
	if kind == "Volume" && region.Rollup != nil && region.Rollup.VolumesUnavailable {
		return subject + " is unknown: the regional volume observation is unavailable."
	}
	switch region.ResourceState(false) {
	case "stale":
		return subject + " is unknown: the regional observation is stale."
	case "truncated":
		return subject + " is unknown: the regional observation is truncated."
	case "missing":
		return subject + " is unknown: no regional observation is available."
	default:
		return subject + " is absent from the current complete regional observation."
	}
}

func regionVolumeTable(current view, region globalview.Region, entries []volumeEntry) table {
	volumes := volumeTable(current, entries)
	if region.Rollup != nil && region.Rollup.VolumesUnavailable {
		volumes.Empty = "This region could not read its volume list."
	}
	return volumes
}

// unreadVolumeRegions lists the regions whose last rollup could not read
// their volumes, for the global volume list.
func unreadVolumeRegions(regions []globalview.Region) []string {
	var out []string
	for _, region := range regions {
		if region.Rollup != nil && region.Rollup.VolumesUnavailable {
			out = append(out, upper(region.Cell))
		}
	}
	return out
}

