func fullJournal() (*Journal, *fakeInsights, *fakeDecisions) {
	history := observability.NewHistory(observability.HistoryConfig{})
	for minute := 120; minute >= 0; minute-- {
		at := time.Now().Add(-time.Duration(minute) * time.Minute)
		history.Append(at, []observability.Sample{
			{Metric: observability.HistCPUUtilization, Labels: observability.L("member", "ctl-1"), Value: 0.4},
			{Metric: observability.HistMembersAnswering, Value: 2},
			{Metric: observability.HistFSRatio, Labels: observability.L("member", "ctl-1", "role", "nats"),
				Value: 0.7 + float64(120-minute)*0.001},
			{Metric: observability.HistOCICalls, Labels: observability.L("operation", "compute GET /instances"),
				Value: float64(120-minute) * 60, Counter: true},
		})
	}
	source := &fakeInsights{evaluation: insights.Evaluation{At: testNow,
		Insights: []insights.Insight{testInsight("disk:ctl-1", "ctl-1 nats filesystem full in about 2d", insights.SeverityWarning, "fra")},
		Counts:   insights.Counts{Warning: 1}}}
	decisions := &fakeDecisions{decisions: testDecisions()}
	journal := &Journal{Decisions: decisions, History: history, Insights: source, Summaries: fakeSummaries{},
		Local:  func(context.Context) regionview.Summary { return testRegions()[0] },
		Global: testGlobalView(),
		Versions: fakeVersions{{Region: "fra", Kind: "controller", Unit: "ctl-1", Version: "v0.43.0"},
			{Region: "fra", Kind: "controller", Unit: "ctl-2", Version: "v0.42.1"},
			{Region: "sfo", Kind: "seat", Unit: "orders-1", Version: "terrabase 3.8.1"}},
		Rollouts: fakeRollouts{{ID: "0000000000N6KCZG3MWDGZ0WBE", Release: "v0.43.0", Phase: "batch-1", PhaseStarted: testNow.Add(-time.Hour),
			PhaseDeadline: testNow.Add(-time.Minute)}},
		Volumes: fakeVolumes{{ID: "vol-stuck", Host: "host-a", State: "attaching", StateSince: testNow.Add(-time.Hour)}},
		Qualification: fakeQualification{{Release: "v0.43.1-rc.1", Status: "running", Time: testNow,
			Suites: []QualificationStep{{Name: "rolling upgrade", Status: "running"}}}},
		Inventory: fakeInventory{{Kind: "instance", ID: "ocid1.instance.x", Name: "host-old", State: "STOPPED", Drift: "unmanaged"}}}
	return journal, source, decisions
}

func journalDashboard(options Options) (*Dashboard, *fakeInsights, *fakeDecisions) {
	journal, source, decisions := fullJournal()
	options.Journal = journal
	options.Snapshots = fixedSnapshots{snapshot: memberSnapshot()}
	options.Health = readyHealth(true)
	return newTestDashboard(options), source, decisions
}

func (dashboard *Dashboard) loadJournal(ctx context.Context, current *view) {
	holder := dashboard.journal.Load()
	if holder == nil {
		return
	}
	journal := *holder
	current.Journal = &journal
	needs := current.Page.needs
	if journal.Global != nil {
		current.Global = journal.Global.Regions()
	}
	if needs&needLocal != 0 && journal.Local != nil {
		summary := journal.Local(ctx)
		current.LocalSummary = &summary
	}
	if journal.Insights != nil {
		evaluation := journal.Insights.Current()
		current.Evaluation = &evaluation
	}
	if needs&needSummaries != 0 && journal.Summaries != nil {
		for _, window := range summaryWindows {
			summary, err := dashboard.summaries.get(ctx, window.String(), func(ctx context.Context) (insights.Summary, error) {
				return journal.Summaries.Summary(ctx, window)
			})
			if err != nil {
				current.Unavailable = append(current.Unavailable, "summary "+window.String())
				continue
			}
			current.Summaries = append(current.Summaries, summary)
		}
	}
	if current.Page.decisions != nil && journal.Decisions != nil {
		if query := current.Page.decisions(*current); query != nil {
			key, _ := json.Marshal(query)
			result, err := dashboard.decisions.get(ctx, string(key), func(ctx context.Context) (decisionlog.Result, error) {
				return journal.Decisions.Query(ctx, *query)
			})
			if err != nil {
				current.Unavailable = append(current.Unavailable, "decision journal")
			} else {
				current.Decisions = &result
			}
		}
	}
	id := current.State.param("id")
	if id == "" && current.Page.chain != nil {
		id = current.Page.chain(*current)
	}
	if needs&needChain != 0 && id != "" && journal.Decisions != nil {
		// Cached like the decision queries: a chain lookup may fan out to
		// every linked region, and every open stream re-renders each tick.
		chain, err := dashboard.chains.get(ctx, id, func(ctx context.Context) (decisionlog.Chain, error) {
			return journal.Decisions.Chain(ctx, id)
		})
		switch {
		case err == nil:
			current.Chain = &chain
		case !errors.Is(err, decisionlog.ErrNotFound):
			current.Unavailable = append(current.Unavailable, "decision chain")
		}
	}
	if needs&needVersions != 0 {
		current.loadVersions(ctx)
	}
	if needs&needCapacity != 0 && journal.Capacity != nil {
		current.loadCapacity(ctx, journal.Capacity)
	}
	if needs&needRollouts != 0 && journal.Rollouts != nil {
		if rollouts, err := dashboard.rollouts.get(ctx, "recent", journal.Rollouts.Rollouts); err != nil {
			current.Unavailable = append(current.Unavailable, "rollouts")
		} else {
			current.Rollouts = rollouts
		}
	}
	if needs&needRollout != 0 && journal.Rollouts != nil {
		rollout, err := dashboard.rollout.get(ctx, current.Path["id"], func(ctx context.Context) (insights.Rollout, error) {
			return journal.Rollouts.Rollout(ctx, current.Path["id"])
		})
		switch {
		case err == nil:
			current.Rollout = &rollout
		case !errors.Is(err, ErrRolloutNotFound):
			current.Unavailable = append(current.Unavailable, "rollouts")
		}
	}
	if needs&needVolumes != 0 && journal.Volumes != nil {
		if volumes, err := journal.Volumes.Volumes(ctx); err != nil {
			current.Unavailable = append(current.Unavailable, "volumes")
		} else {
			current.Volumes = volumes
		}
	}
	if needs&needQualification != 0 && journal.Qualification != nil {
		if runs, err := journal.Qualification.Qualifications(ctx); err != nil {
			current.Unavailable = append(current.Unavailable, "qualification")
		} else {
			current.Qualifications = runs
		}
	}
	if needs&needInventory != 0 && journal.Inventory != nil {
		observation, err := journal.Inventory.Inventory(ctx)
		current.Inventory, current.InventoryObservation = observation.Items, &observation
		if err != nil {
			current.Unavailable = append(current.Unavailable, "OCI inventory")
		}
	}
}

// localRegion is this member's region token.
func (current view) localRegion() string { return strings.ToLower(current.cell()) }

// region is the selected region, defaulting to this member's.
func (current view) region() string {
	if current.State.Region != "" {
		return current.State.Region
	}
	return current.localRegion()
}

// remote reports that the selected region is not this member's, so only its
// summary (not its live member detail) is available here.
func (current view) remote() bool {
	return current.State.Region != "" && current.State.Region != current.localRegion()
}

// queryNow rounds the clock so repeated ticks share the decision cache.
func (current view) queryNow() time.Time { return current.Now.Truncate(decisionCacheTTL) }

func (current view) since(minimum time.Duration) time.Time {
	return current.queryNow().Add(-max(current.State.Range.Duration, minimum))
}

func regionDecisions(current view) *decisionlog.Query {
	return &decisionlog.Query{Regions: []string{current.region()}, Since: current.since(0), Limit: 100}
}

// journalDecisions reads the decisions page filters.
func journalDecisions(current view) *decisionlog.Query {
	query := decisionlog.Query{Regions: current.State.regionFilter(), Actors: current.State.list("actor"),
		Subject: strings.ToLower(current.State.param("q")), Since: current.since(0), Limit: 500}
	for _, kind := range current.State.list("kind") {
		query.Kinds = append(query.Kinds, decisionlog.Kind(kind))
	}
	for _, status := range current.State.list("status") {
		query.Statuses = append(query.Statuses, decisionlog.Status(status))
	}
	return &query
}

func (query Query) Normalized() Query {
	if query.Limit <= 0 {
		query.Limit = DefaultQueryLimit
	}
	query.Limit = min(query.Limit, MaxQueryLimit)
	query.Regions = slices.Clone(query.Regions)
	for index, region := range query.Regions {
		query.Regions[index] = strings.ToLower(region)
	}
	query.Subject = strings.ToLower(query.Subject)
	return query
}

// Matches reports whether a decision satisfies every filter of a normalized
// query.
func (query Query) Matches(decision Decision) bool {
	if len(query.Regions) > 0 && !slices.Contains(query.Regions, decision.Region) {
		return false
	}
	if len(query.Kinds) > 0 && !slices.Contains(query.Kinds, decision.Kind) {
		return false
	}
	if len(query.Actors) > 0 && !slices.ContainsFunc(query.Actors, func(actor string) bool {
		return actor == decision.Actor.Slice || actor == decision.Actor.Slice+"/"+decision.Actor.Member
	}) {
		return false
	}
	if query.SubjectKind != "" && query.SubjectKind != decision.Subject.Kind {
		return false
	}
	if query.SubjectID != "" && query.SubjectID != decision.Subject.ID {
		return false
	}
	if query.Subject != "" && !containsFold(decision.Subject.ID, query.Subject) &&
		!containsFold(decision.Subject.Name, query.Subject) && !containsFold(decision.Summary, query.Subject) {
		return false
	}
	if len(query.Statuses) > 0 && !slices.Contains(query.Statuses, decision.Status) {
		return false
	}
	if query.ParentID != "" && query.ParentID != decision.ParentID {
		return false
	}
	if !query.Since.IsZero() && decision.Time.Before(query.Since) {
		return false
	}
	if !query.Until.IsZero() && !decision.Time.Before(query.Until) {
		return false
	}
	return true
}

func containsFold(value, lowerNeedle string) bool {
	return value != "" && strings.Contains(strings.ToLower(value), lowerNeedle)
}

// SortNewestFirst orders decisions by time, newest first, breaking ties by
// ID so merged regional results are stable.
func SortNewestFirst(decisions []Decision) {
	slices.SortStableFunc(decisions, func(left, right Decision) int {
		if order := right.Time.Compare(left.Time); order != 0 {
			return order
		}
		return cmp.Compare(right.ID, left.ID)
	})
}

// BuildChain assembles the chain containing id from a set of decisions. It
// follows ParentID upward to the root and then collects every descendant of
// the root. ok is false when id is not in the set.
func BuildChain(decisions []Decision, id string) (Chain, bool) {
	byID := make(map[string]Decision, len(decisions))
	children := map[string][]string{}
	for _, decision := range decisions {
		byID[decision.ID] = decision
		if decision.ParentID != "" {
			children[decision.ParentID] = append(children[decision.ParentID], decision.ID)
		}
	}
	current, ok := byID[id]
	if !ok {
		return Chain{}, false
	}
	seen := map[string]bool{current.ID: true}
	for current.ParentID != "" {
		parent, found := byID[current.ParentID]
		if !found || seen[parent.ID] {
			break
		}
		seen[parent.ID] = true
		current = parent
	}
	chain := Chain{Root: current}
	visited := map[string]bool{}
	queue := []string{current.ID}
	// The walk is bounded by the input; only the returned list is capped,
	// after Latest is known.
	for len(queue) > 0 {
		next := queue[0]
		queue = queue[1:]
		if visited[next] {
			continue
		}
		visited[next] = true
		chain.Decisions = append(chain.Decisions, byID[next])
		queue = append(queue, children[next]...)
	}
	slices.SortStableFunc(chain.Decisions, func(left, right Decision) int {
		if order := left.Time.Compare(right.Time); order != 0 {
			return order
		}
		return cmp.Compare(left.ID, right.ID)
	})
	chain.Latest = chain.Decisions[len(chain.Decisions)-1]
	if len(chain.Decisions) > MaxQueryLimit {
		chain.Truncated = true
		kept := make([]Decision, 0, MaxQueryLimit)
		newest := chain.Decisions[len(chain.Decisions)-(MaxQueryLimit-2):]
		for _, decision := range chain.Decisions[:len(chain.Decisions)-len(newest)] {
			if decision.ID == chain.Root.ID || decision.ID == id {
				kept = append(kept, decision)
			}
		}
		chain.Decisions = append(kept, newest...)
	}
	return chain, true
}

