func NewEventBus(capacity int) *EventBus {
	if capacity <= 0 {
		capacity = DefaultEventCapacity
	}
	return &EventBus{ring: make([]Event, capacity), subscribers: map[*eventSubscriber]struct{}{}}
}

// initLocked gives a zero-value EventBus the default ring and subscriber set,
// so a bus that was declared rather than built with NewEventBus cannot divide
// by zero on the log path. bus.mu must be held.
func (bus *EventBus) initLocked() {
	if len(bus.ring) == 0 {
		bus.ring = make([]Event, DefaultEventCapacity)
	}
	if bus.subscribers == nil {
		bus.subscribers = map[*eventSubscriber]struct{}{}
	}
}

// Publish stores an event, assigning its sequence and a missing timestamp,
// and offers it to every subscriber. It returns the stored event.
func (bus *EventBus) Publish(event Event) Event {
	if bus == nil {
		return event
	}
	if event.Time.IsZero() {
		event.Time = time.Now().UTC()
	}
	bus.mu.Lock()
	bus.initLocked()
	bus.sequence++
	event.Sequence = bus.sequence
	index := (bus.start + bus.size) % len(bus.ring)
	if bus.size == len(bus.ring) {
		bus.start = (bus.start + 1) % len(bus.ring)
	} else {
		bus.size++
	}
	bus.ring[index] = event
	for subscriber := range bus.subscribers {
		select {
		case subscriber.events <- event:
		default:
			bus.dropped.Add(1)
		}
	}
	bus.mu.Unlock()
	bus.published.Add(1)
	return event
}

// Recent returns up to limit of the newest events, oldest first. A
// non-positive limit returns the whole ring.
func (bus *EventBus) Recent(limit int) []Event {
	return bus.Since(0, limit)
}

// Since returns up to limit events with a sequence greater than after, oldest
// first, keeping the newest when more are available. A dashboard reconnecting
// with its last seen sequence uses it to resume without duplicates.
func (bus *EventBus) Since(after uint64, limit int) []Event {
	if bus == nil {
		return nil
	}
	bus.mu.Lock()
	defer bus.mu.Unlock()
	events := make([]Event, 0, bus.size)
	for offset := range bus.size {
		event := bus.ring[(bus.start+offset)%len(bus.ring)]
		if event.Sequence > after {
			events = append(events, event)
		}
	}
	if limit > 0 && len(events) > limit {
		events = events[len(events)-limit:]
	}
	return events
}

// query string, so a filtered page is a plain link and works without JS.
type eventFilter struct {
	Level     string
	Component string
	Search    string
	// At centres the list on a moment: only events within eventWindow of
	// it match.
	At time.Time
}

// eventWindow is how far around a clicked chart point the events page looks.
const eventWindow = 5 * time.Minute

var levelNames = []string{"debug", "info", "warn", "error"}

func parseEventFilter(query url.Values) eventFilter {
	filter := eventFilter{}
	if level := strings.ToLower(query.Get("level")); slices.Contains(levelNames, level) {
		filter.Level = level
	}
	if component := query.Get("component"); validComponent(component) {
		filter.Component = component
	}
	if search := strings.TrimSpace(query.Get("q")); search != "" && validSearch(search) {
		filter.Search = strings.ToLower(search)
	}
	if at, err := time.Parse(time.RFC3339, query.Get("at")); err == nil {
		filter.At = at.UTC()
	}
	return filter
}

func eventContains(event observability.Event, lowerNeedle string) bool {
	if strings.Contains(strings.ToLower(event.Message), lowerNeedle) ||
		strings.Contains(strings.ToLower(event.Component), lowerNeedle) {
		return true
	}
	for key, value := range event.Attrs {
		if strings.Contains(strings.ToLower(key+"="+value), lowerNeedle) {
			return true
		}
	}
	return false
}

func validComponent(component string) bool {
	if component == "" || len(component) > 64 {
		return false
	}
	for _, char := range component {
		if !(char >= 'a' && char <= 'z' || char >= '0' && char <= '9' || strings.ContainsRune("._-", char)) {
			return false
		}
	}
	return true
}

func (filter eventFilter) matches(event observability.Event) bool {
	if filter.Component != "" && event.Component != filter.Component {
		return false
	}
	if !filter.At.IsZero() && (event.Time.Before(filter.At.Add(-eventWindow)) ||
		event.Time.After(filter.At.Add(eventWindow))) {
		return false
	}
	if filter.Search != "" && !eventContains(event, filter.Search) {
		return false
	}
	if filter.Level == "" {
		return true
	}
	var minimum, level slog.Level
	_ = minimum.UnmarshalText([]byte(filter.Level))
	if err := level.UnmarshalText([]byte(event.Level)); err != nil {
		return true
	}
	return level >= minimum
}

// apply returns at most limit matching events, newest first.
func (filter eventFilter) apply(events []observability.Event, limit int) []observability.Event {
	result := make([]observability.Event, 0, min(limit, len(events)))
	for index := len(events) - 1; index >= 0 && len(result) < limit; index-- {
		if filter.matches(events[index]) {
			result = append(result, events[index])
		}
	}
	return result
}

